14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let mut raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    let mut used_args = Vec::<clap::Id>::new();
45	    while let Some(arg) = raw_args.next(&mut cursor) {
46	        let current_state = next_state;
47	        next_state = ParseState::ValueDone;
48	        debug!(
49	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
50	            arg.to_value_os(),
51	        );
52	        if let ParseState::Opt(state) = &current_state {
53	            // A value terminator ends a multi-value option regardless of the
54	            // word's shape: unlike a flag-like word, it never starts a new
55	            // argument, and unlike any other word, it is never one of the
56	            // option's values. A flag-shaped terminator only wins over flag
57	            // parsing when the option accepts hyphen values, matching the
58	            // parser's precedence.
59	            let opt = state.opt;
60	            if is_value_terminator(opt, &arg)
61	                && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
62	            {
63	                if cursor == target_cursor {
64	                    // The cursor sits on the terminator itself. Complete as if
65	                    // it had already been submitted and an empty word followed,
66	                    // so ordinary completion resumes and the terminator is not
67	                    // offered as a candidate.
68	                    raw_args.insert(&target_cursor, [OsString::new()]);
69	                    let mut word_cursor = target_cursor;
70	                    let word = raw_args
71	                        .next(&mut word_cursor)
72	                        .expect("an empty word was just inserted");
73	                    return complete_arg(
74	                        &word,
75	                        current_cmd,
76	                        current_dir,
77	                        pos_index,
78	                        is_escaped,
79	                        ParseState::ValueDone,
80	                        &used_args,
81	                    );
82	                }
83	                next_state = ParseState::ValueDone;
84	                continue;
85	            }
86	        }
87	        if cursor == target_cursor {
88	            return complete_arg(
89	                &arg,
90	                current_cmd,
91	                current_dir,
92	                pos_index,
93	                is_escaped,
94	                current_state,
95	                &used_args,
96	            );
97	        }
98	
99	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
100	            if let Ok(value) = arg.to_value() {
101	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
102	                    current_cmd = next_cmd;
103	                    pos_index = 1;
104	                    used_args.clear();
105	                    continue;
106	                }
107	            }
108	        }
109	
110	        // A strict delimited group whose previous word opened another fragment
111	        // (a trailing delimiter) or went invalid owns the next word outright: a
112	        // flag, the `--` escape, or a subcommand name is then another value of
113	        // the group, never a scope switch. A continuation word that fills the
114	        // group closes it; otherwise the group stays pending for its remaining
115	        // fragments.
116	        if let ParseState::Opt(state) = &current_state {
117	            if state.is_strict_group() && (state.open || state.invalid) {
118	                let mut state = state.clone();
119	                state.observe(arg.to_value_os(), false);
120	                next_state =
121	                    if !state.invalid && !state.open && state.used.len() == state.capacity() {
122	                        ParseState::ValueDone
123	                    } else {
124	                        ParseState::Opt(state)
125	                    };
126	                continue;
127	            }
128	        }
129	
130	        if is_escaped {
131	            (next_state, pos_index) =
132	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
133	        } else if arg.is_escape() {
134	            is_escaped = true;
135	            // Like the parser, `--` jumps straight to a `last(true)`
136	            // positional, skipping any unfilled positionals.
137	            if let Some(last_index) = current_cmd
138	                .get_positionals()
139	                .filter(|p| p.is_last_set())
140	                .filter_map(|p| p.get_index())
141	                .max()
142	            {
143	                pos_index = last_index;
144	            }
145	        } else if opt_allows_hyphen(&current_state, &arg) {
146	            match current_state {
147	                ParseState::Opt(mut state) => {
148	                    state.observe(arg.to_value_os(), false);
149	                    next_state = state.finish();
150	                }
151	                _ => unreachable!("else branch is only reachable in Opt state"),
152	            }
153	        } else if let Some((flag, value)) = arg.to_long() {
154	            if let Ok(flag) = flag {
155	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
156	
157	                if let Some(opt) = opt {
158	                    record_used_arg(&mut used_args, opt.get_id());
159	                    if opt.get_num_args().expect("built").takes_values() {
160	                        // An attached value (`--opt=value`) counts toward the
161	                        // option's values just like a space-separated one, so
162	                        // that completing after `--opt=value` sees the same
163	                        // state as completing after `--opt value`.
164	                        // An empty attached value (`--opt=`) types no value
165	                        // yet, so the option stays pending.
166	                        let mut state = OptState::new(opt);
167	                        if let Some(value) = value.filter(|v| !v.is_empty()) {
168	                            state.observe(value, true);
169	                        }
170	                        next_state = state.finish();
171	                    };
172	                } else if pos_allows_hyphen(current_cmd, pos_index) {
173	                    (next_state, pos_index) =
174	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
175	                }
176	            }
177	        } else if let Some(short) = arg.to_short() {
178	            let (_, matched_opts, takes_value_opt, mut short) =
179	                parse_shortflags(current_cmd, short);
180	            for opt in &matched_opts {
181	                record_used_arg(&mut used_args, opt.get_id());
182	            }
183	            if let Some(opt) = takes_value_opt {
184	                // An attached value (`-ovalue`, `-o=value`) counts toward the
185	                // option's values just like a space-separated one. An empty
186	                // attached value (`-o=`) types no value yet, so the option
187	                // stays pending instead of being treated as satisfied.
188	                let mut state = OptState::new(opt);
189	                if let Some(value) = short
190	                    .next_value_os()
191	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
192	                    .filter(|v| !v.is_empty())
193	                {
194	                    state.observe(value, true);
195	                }
196	                next_state = state.finish();
197	            } else if pos_allows_hyphen(current_cmd, pos_index) {
198	                (next_state, pos_index) =
199	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
200	            }
201	        } else {
202	            match current_state {
203	                ParseState::ValueDone | ParseState::Pos(..) => {
204	                    (next_state, pos_index) =
205	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
206	                }
207	                ParseState::Opt(mut state) => {
208	                    state.observe(arg.to_value_os(), false);
209	                    next_state = state.finish();
210	                }
211	            }
212	        }
213	    }
214	
215	    Err(std::io::Error::other("no completion generated"))
216	}
