218	#[derive(Debug, PartialEq, Eq, Clone)]
219	enum ParseState<'a> {
220	    /// Parsing a value done, there is no state to record.
221	    ValueDone,
222	
223	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
224	    Pos((usize, usize)),
225	
226	    /// Parsing a optional flag argument
227	    Opt(OptState<'a>),
228	}
229	
230	/// State kept while the values of an option are still being parsed.
231	#[derive(Debug, PartialEq, Eq, Clone)]
232	struct OptState<'a> {
233	    opt: &'a clap::Arg,
234	    /// Shell-word values consumed, counted the way the parser does so that
235	    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments
236	    /// rather than delimiter-separated fragments.
237	    words: usize,
238	    /// Canonical possible-value names of the valid, committed fragments of
239	    /// the current occurrence. Only populated for strict delimited groups.
240	    used: Vec<String>,
241	    /// Whether the most recent shell word ended with the value delimiter, so
242	    /// the word under the cursor is still filling this group (and may not
243	    /// switch scope no matter how it is shaped).
244	    open: bool,
245	    /// Whether a committed fragment of the current group was invalid (empty,
246	    /// unknown, duplicated, or past the group's capacity). Such a group stays
247	    /// locked on value completion and never yields candidates or lets a later
248	    /// word switch scope.
249	    invalid: bool,
250	}
251	
252	impl<'a> OptState<'a> {
253	    fn new(opt: &'a clap::Arg) -> Self {
254	        Self {
255	            opt,
256	            words: 0,
257	            used: Vec::new(),
258	            open: false,
259	            invalid: false,
260	        }
261	    }
262	
263	    fn is_strict_group(&self) -> bool {
264	        is_strict_group_arg(self.opt)
265	    }
266	
267	    /// Maximum number of values the option accepts; for strict delimited
268	    /// groups this is the number of fragments allowed in one occurrence.
269	    fn capacity(&self) -> usize {
270	        self.opt.get_num_args().expect("built").max_values()
271	    }
272	
273	    /// Record a shell word as a value of this option.
274	    ///
275	    /// `attached` marks a value glued to its flag (`--opt=a,b`). For options
276	    /// whose delimiter is not a strict group, such a word counts every
277	    /// delimiter-separated fragment toward the value range; a space-separated
278	    /// word counts once. For strict groups the fragments are instead validated
279	    /// into `used`, except the empty slot still being typed after a trailing
280	    /// delimiter.
281	    fn observe(&mut self, word: &OsStr, attached: bool) {
282	        if !self.is_strict_group() {
283	            let count = if attached {
284	                attached_value_count(self.opt, word)
285	            } else {
286	                1
287	            };
288	            self.words += count;
289	            return;
290	        }
291	
292	        self.words += 1;
293	        if self.invalid {
294	            return;
295	        }
296	        let delimiter = self.opt.get_value_delimiter().expect("strict group");
297	        let capacity = self.capacity();
298	        self.open = word.to_string_lossy().ends_with(delimiter);
299	        let Some(word) = word.to_str() else {
300	            self.invalid = true;
301	            return;
302	        };
303	        let mut fragments = word.split(delimiter);
304	        if self.open {
305	            // A trailing delimiter opens the slot still being typed, so its
306	            // empty fragment is not a committed value.
307	            fragments.next_back();
308	        }
309	        for fragment in fragments {
310	            if self.used.len() >= capacity {
311	                self.invalid = true;
312	                break;
313	            }
314	            match canonical_possible_value(self.opt, fragment) {
315	                Some(name) if !self.used.contains(&name) => self.used.push(name),
316	                _ => {
317	                    // Empty (also a doubled delimiter), unknown, or duplicated
318	                    // fragment: the parser would reject this group.
319	                    self.invalid = true;
320	                    break;
321	                }
322	            }
323	        }
324	    }
325	
326	    /// Consume a value and return the state parsing should resume with.
327	    ///
328	    /// The delimiter separates several fragments within one shell word, so a
329	    /// word that does not end with the delimiter is a complete value group and
330	    /// ordinary parsing resumes on the next word. A trailing delimiter instead
331	    /// opens a fragment still being typed, and an invalid committed fragment
332	    /// cannot be salvaged; both keep the group locked on values. An empty
333	    /// attached value (`--opt=`) leaves the option waiting for its first value.
334	    fn finish(self) -> ParseState<'a> {
335	        if self.is_strict_group() {
336	            if self.words == 0 || self.invalid || self.open {
337	                ParseState::Opt(self)
338	            } else {
339	                ParseState::ValueDone
340	            }
341	        } else if self.words >= self.capacity() {
342	            ParseState::ValueDone
343	        } else {
344	            ParseState::Opt(self)
345	        }
346	    }
347	}
348	
349	/// Whether an option's values form a delimited group that can hold more than
350	/// one fragment and whose fragments are validated while typed.
351	///
352	/// Single-value options (a maximum of one) are excluded: their delimiter only
353	/// joins several suggestions into one word, so completed fragments are not
354	/// validated against each other.
355	fn is_strict_group_arg(arg: &clap::Arg) -> bool {
356	    arg.get_value_delimiter().is_some()
357	        && arg.get_num_args().expect("built").max_values() > 1
358	        && possible_values(arg).is_some()
359	}
360	
361	/// The canonical possible-value name for `fragment`, honoring aliases and the
362	/// argument's case-insensitivity, or `None` when it is not a legal value.
363	fn canonical_possible_value(arg: &clap::Arg, fragment: &str) -> Option<String> {
364	    let ignore_case = arg.is_ignore_case_set();
365	    possible_values(arg)?
366	        .find(|value| value.matches(fragment, ignore_case))
367	        .map(|value| value.get_name().to_owned())
368	}
369	
370	/// Complete the word under the cursor for a strict delimited group.
371	///
372	/// Fragments already committed in earlier shell words are read from `state`;
373	/// fragments committed within the word under the cursor are validated here.
374	/// The fragment still being typed is matched against the possible values, and
375	/// every suggestion keeps the typed prefix (prior fragments and delimiters).
376	/// Any empty, unknown, duplicated, or over-capacity fragment yields an empty
377	/// result.
378	fn complete_strict_group(cursor: &str, state: &OptState<'_>) -> Vec<CompletionCandidate> {
379	    debug!(
380	        "complete_strict_group: arg={:?}, cursor={cursor:?}, used={:?}, invalid={}",
381	        state.opt.get_id(),
382	        state.used,
383	        state.invalid
384	    );
385	    if state.invalid {
386	        return Vec::new();
387	    }
388	    let delimiter = state.opt.get_value_delimiter().expect("strict group");
389	    let capacity = state.capacity();
390	
391	    let ends_with_delimiter = cursor.ends_with(delimiter);
392	    let mut parts = cursor.split(delimiter);
393	    let typed = if ends_with_delimiter {
394	        // The cursor sits right after a delimiter: the trailing empty element
395	        // is the fresh fragment being typed, not a committed value.
396	        parts.next_back();
397	        ""
398	    } else {
399	        parts.next_back().unwrap_or("")
400	    };
401	
402	    let mut used = state.used.clone();
403	    for fragment in parts {
404	        if used.len() >= capacity {
405	            return Vec::new();
406	        }
407	        match canonical_possible_value(state.opt, fragment) {
408	            Some(name) if !used.contains(&name) => used.push(name),
409	            _ => return Vec::new(),
410	        }
411	    }
412	
413	    if used.len() >= capacity {
414	        // Every slot is taken; there is no room for another fragment.
415	        return Vec::new();
416	    }
417	
418	    // Retain the text typed before the current fragment, including the last
419	    // delimiter, so suggestions replace only the fragment under the cursor.
420	    let prefix = cursor
421	        .rfind(delimiter)
422	        .map(|pos| cursor[..pos + delimiter.len_utf8()].to_owned());
423	
424	    let possible = possible_values(state.opt).expect("strict group");
425	    let mut values = complete_candidates_str(typed, possible_value_candidates(possible));
426	    // A value already committed to the group cannot be repeated.
427	    values.retain(|candidate| {
428	        candidate
429	            .get_value()
430	            .to_str()
431	            .is_none_or(|name| !used.iter().any(|used| used == name))
432	    });
433	
434	    if let Some(prefix) = prefix {
435	        values = values
436	            .into_iter()
437	            .map(|comp| comp.add_prefix(prefix.clone()))
438	            .collect();
439	    }
440	    values = values
441	        .into_iter()
442	        .map(|comp| {
443	            if comp.get_tag().is_some() {
444	                comp
445	            } else {
446	                comp.tag(Some(state.opt.to_string().into()))
447	            }
448	        })
449	        .collect();
450	
451	    values
452	}
