454	fn complete_arg(
455	    arg: &clap_lex::ParsedArg<'_>,
456	    cmd: &clap::Command,
457	    current_dir: Option<&std::path::Path>,
458	    pos_index: usize,
459	    is_escaped: bool,
460	    state: ParseState<'_>,
461	    used_args: &[clap::Id],
462	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
463	    debug!(
464	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
465	        arg,
466	        cmd.get_name(),
467	        current_dir,
468	        pos_index,
469	        state
470	    );
471	    let mut completions = Vec::<CompletionCandidate>::new();
472	
473	    match state {
474	        ParseState::ValueDone => {
475	            if !is_escaped {
476	                if let Ok(value) = arg.to_value() {
477	                    completions.extend(complete_subcommand(value, cmd));
478	                }
479	            }
480	
481	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
482	                completions.extend(complete_arg_value(
483	                    arg.to_value(),
484	                    positional,
485	                    current_dir,
486	                    0,
487	                ));
488	            }
489	            if !is_escaped {
490	                completions.extend(complete_option(arg, cmd, current_dir));
491	            }
492	        }
493	        ParseState::Pos((_, num_arg)) => {
494	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
495	                completions.extend(complete_arg_value(
496	                    arg.to_value(),
497	                    positional,
498	                    current_dir,
499	                    num_arg.saturating_sub(1),
500	                ));
501	                if !is_escaped
502	                    && positional
503	                        .get_num_args()
504	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
505	                {
506	                    completions.extend(complete_option(arg, cmd, current_dir));
507	                }
508	            }
509	        }
510	        ParseState::Opt(state) => {
511	            if state.is_strict_group() {
512	                // Every word belongs to the pending delimited group until it is
513	                // complete; it is never an option, positional, or subcommand.
514	                if let Ok(cursor) = arg.to_value() {
515	                    completions.extend(complete_strict_group(cursor, &state));
516	                }
517	            } else {
518	                let opt = state.opt;
519	                // `words` counts already-consumed values; the word under the
520	                // cursor is the next one, so the option sees one more value.
521	                let count = state.words + 1;
522	                completions.extend(complete_arg_value(
523	                    arg.to_value(),
524	                    opt,
525	                    current_dir,
526	                    count.saturating_sub(1),
527	                ));
528	                let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
529	                if count > min && can_switch_to_other_arg(opt, arg) {
530	                    // The option's required values are satisfied and this word
531	                    // would be parsed as a new flag rather than another value, so
532	                    // also complete it as a positional, flag, option or subcommand.
533	                    completions.extend(complete_arg(
534	                        arg,
535	                        cmd,
536	                        current_dir,
537	                        pos_index,
538	                        is_escaped,
539	                        ParseState::ValueDone,
540	                        used_args,
541	                    )?);
542	                }
543	            }
544	        }
545	    }
546	    filter_unavailable_args(&mut completions, cmd, used_args);
547	    if completions.iter().any(|a| !a.is_hide_set()) {
548	        completions.retain(|a| !a.is_hide_set());
549	    }
550	    dedup_argument_candidates(&mut completions, arg.is_empty());
551	
552	    let mut tags = Vec::new();
553	    for candidate in &completions {
554	        let tag = candidate.get_tag().cloned();
555	        if !tags.contains(&tag) {
556	            tags.push(tag);
557	        }
558	    }
559	    completions.sort_by_key(|c| {
560	        (
561	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
562	            c.get_display_order(),
563	        )
564	    });
565	
566	    Ok(completions)
567	}
568	
569	fn complete_option(
570	    arg: &clap_lex::ParsedArg<'_>,
571	    cmd: &clap::Command,
572	    current_dir: Option<&std::path::Path>,
573	) -> Vec<CompletionCandidate> {
574	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
575	    let mut completions = Vec::<CompletionCandidate>::new();
576	    if arg.is_empty() {
577	        completions.extend(longs_and_visible_aliases(cmd));
578	        completions.extend(hidden_longs_aliases(cmd));
579	
580	        let dash_or_arg = if arg.is_empty() {
581	            "-".into()
582	        } else {
583	            arg.to_value_os().to_string_lossy()
584	        };
585	        completions.extend(
586	            shorts_and_visible_aliases(cmd)
587	                .into_iter()
588	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
589	        );
590	    } else if arg.is_stdio() {
591	        // HACK: Assuming knowledge of is_stdio
592	        let dash_or_arg = if arg.is_empty() {
593	            "-".into()
594	        } else {
595	            arg.to_value_os().to_string_lossy()
596	        };
597	        completions.extend(
598	            shorts_and_visible_aliases(cmd)
599	                .into_iter()
600	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
601	        );
602	
603	        completions.extend(longs_and_visible_aliases(cmd));
604	        completions.extend(hidden_longs_aliases(cmd));
605	    } else if arg.is_escape() {
606	        // HACK: Assuming knowledge of is_escape
607	        completions.extend(longs_and_visible_aliases(cmd));
608	        completions.extend(hidden_longs_aliases(cmd));
609	    } else if let Some((flag, value)) = arg.to_long() {
610	        if let Ok(flag) = flag {
611	            if let Some(value) = value {
612	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
613	                    if is_strict_group_arg(arg) {
614	                        // The whole attached word is the delimited group being
615	                        // typed, so its committed fragments are validated in
616	                        // place and only the fragment after the last delimiter
617	                        // is offered; the flag spelling is re-prefixed below.
618	                        if let Some(value) = value.to_str() {
619	                            let state = OptState::new(arg);
620	                            completions.extend(
621	                                complete_strict_group(value, &state)
622	                                    .into_iter()
623	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
624	                            );
625	                        }
626	                    } else {
627	                        completions.extend(
628	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
629	                                .into_iter()
630	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
631	                        );
632	                    }
633	                }
634	            } else {
635	                completions.extend(
636	                    longs_and_visible_aliases(cmd)
637	                        .into_iter()
638	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
639	                );
640	                completions.extend(
641	                    hidden_longs_aliases(cmd)
642	                        .into_iter()
643	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
644	                );
645	            }
646	        }
647	    } else if let Some(short) = arg.to_short() {
648	        if !short.is_negative_number() {
649	            // Find the first takes_values option.
650	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
651	
652	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
653	            if let Some(opt) = takes_value_opt {
654	                let mut peek_short = short.clone();
655	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
656	                    short.next_flag();
657	                    true
658	                } else {
659	                    false
660	                };
661	
662	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
663	                let group_completions = if is_strict_group_arg(opt) {
664	                    value
665	                        .to_str()
666	                        .map(|value| complete_strict_group(value, &OptState::new(opt)))
667	                        .unwrap_or_default()
668	                } else {
669	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
670	                };
671	                completions.extend(group_completions.into_iter().map(|comp| {
672	                    let sep = if has_equal { "=" } else { "" };
673	                    comp.add_prefix(format!("-{leading_flags}{sep}"))
674	                }));
675	            } else {
676	                completions.extend(
677	                    shorts_and_visible_aliases(cmd)
678	                        .into_iter()
679	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
680	                );
681	            }
682	        }
683	    }
684	    debug!("complete_option: completions={completions:?}");
685	    completions
686	}
