688	fn complete_arg_value(
689	    value: Result<&str, &OsStr>,
690	    arg: &clap::Arg,
691	    current_dir: Option<&std::path::Path>,
692	    arg_index: usize,
693	) -> Vec<CompletionCandidate> {
694	    let mut values = Vec::new();
695	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
696	
697	    let (prefix, value) =
698	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
699	
700	    let value_os = match value {
701	        Ok(value) => OsStr::new(value),
702	        Err(value_os) => value_os,
703	    };
704	
705	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
706	        values.extend(completer.complete_at(arg_index, value_os));
707	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
708	        values.extend(complete_value_candidates(
709	            value_os,
710	            completer.value_candidates(),
711	        ));
712	    } else if let Some(possible_values) = possible_values(arg) {
713	        if let Ok(value) = value {
714	            values.extend(complete_candidates_str(
715	                value,
716	                possible_value_candidates(possible_values),
717	            ));
718	        }
719	    } else {
720	        match arg.get_value_hint() {
721	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
722	                // Should not complete
723	            }
724	            clap::ValueHint::AnyPath => {
725	                values.extend(complete_path(value_os, current_dir, &|_| true));
726	            }
727	            clap::ValueHint::FilePath => {
728	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
729	            }
730	            clap::ValueHint::DirPath => {
731	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
732	            }
733	            clap::ValueHint::ExecutablePath => {
734	                use is_executable::IsExecutable;
735	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
736	            }
737	            clap::ValueHint::CommandName
738	            | clap::ValueHint::CommandString
739	            | clap::ValueHint::CommandWithArguments
740	            | clap::ValueHint::Username
741	            | clap::ValueHint::Hostname
742	            | clap::ValueHint::Url
743	            | clap::ValueHint::EmailAddress => {
744	                // No completion implementation
745	            }
746	            _ => {
747	                // Safe-ish fallback
748	                values.extend(complete_path(value_os, current_dir, &|_| true));
749	            }
750	        }
751	
752	        values.sort();
753	    }
754	
755	    if let Some(prefix) = prefix {
756	        values = values
757	            .into_iter()
758	            .map(|comp| comp.add_prefix(prefix))
759	            .collect();
760	    }
761	    values = values
762	        .into_iter()
763	        .map(|comp| {
764	            if comp.get_tag().is_some() {
765	                comp
766	            } else {
767	                comp.tag(Some(arg.to_string().into()))
768	            }
769	        })
770	        .collect();
771	
772	    debug!("complete_arg_value: values={values:?}");
773	    values
774	}
