776	fn rsplit_delimiter<'s, 'o>(
777	    value: Result<&'s str, &'o OsStr>,
778	    delimiter: Option<char>,
779	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
780	    let delimiter = delimiter?;
781	    let value = value.ok()?;
782	    let pos = value.rfind(delimiter)?;
783	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
784	    Some((Some(prefix), Ok(value)))
785	}
