959	/// Parse the short flags and find the first `takes_values` option.
960	///
961	/// Returns the raw leading flags, every matched argument, the first
962	/// `takes_values` option (if any), and the remaining unparsed flags.
963	fn parse_shortflags<'c, 's>(
964	    cmd: &'c clap::Command,
965	    mut short: clap_lex::ShortFlags<'s>,
966	) -> (
967	    String,
968	    Vec<&'c clap::Arg>,
969	    Option<&'c clap::Arg>,
970	    clap_lex::ShortFlags<'s>,
971	) {
972	    let takes_value_opt;
973	    let mut matched_opts = Vec::new();
974	    let mut leading_flags = String::new();
975	    // Find the first takes_values option.
976	    loop {
977	        match short.next_flag() {
978	            Some(Ok(opt)) => {
979	                leading_flags.push(opt);
980	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
981	                if let Some(opt) = opt {
982	                    matched_opts.push(opt);
983	                }
984	                if opt
985	                    .map(|o| o.get_num_args().expect("built").takes_values())
986	                    .unwrap_or(false)
987	                {
988	                    takes_value_opt = opt;
989	                    break;
990	                }
991	            }
992	            Some(Err(_)) | None => {
993	                takes_value_opt = None;
994	                break;
995	            }
996	        }
997	    }
998	
999	    (leading_flags, matched_opts, takes_value_opt, short)
1000	}
