1020	/// Remove argument candidates that are unavailable given the arguments
1021	/// already present on the command line.
1022	///
1023	/// Two rules apply:
1024	/// - Non-multiple argument groups: once any member of such a group is on the
1025	///   command line, every member of that group (including the selected one and
1026	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
1027	/// - Explicit conflicts: a candidate that conflicts with an already-used
1028	///   argument is removed; conflicts only need to be declared on one side.
1029	///
1030	/// Anything that is not an argument candidate (positional values,
1031	/// subcommands, custom candidates) is left untouched.
1032	fn filter_unavailable_args(
1033	    completions: &mut Vec<CompletionCandidate>,
1034	    cmd: &clap::Command,
1035	    used_args: &[clap::Id],
1036	) {
1037	    if used_args.is_empty() {
1038	        return;
1039	    }
1040	
1041	    // Members of non-multiple groups that already have a member present.
1042	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
1043	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
1044	        let members: Vec<&clap::Id> = group.get_args().collect();
1045	        if members
1046	            .iter()
1047	            .any(|id| used_args.iter().any(|used| used == *id))
1048	        {
1049	            excluded_by_group.extend(members.into_iter().cloned());
1050	        }
1051	    }
1052	
1053	    completions.retain(|candidate| {
1054	        let Some(arg) = candidate
1055	            .get_id()
1056	            .and_then(|id| id.strip_prefix("arg::"))
1057	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
1058	        else {
1059	            return true;
1060	        };
1061	        if excluded_by_group.contains(arg.get_id()) {
1062	            return false;
1063	        }
1064	        !used_args.iter().any(|used_id| {
1065	            cmd.get_arguments()
1066	                .find(|a| a.get_id() == used_id)
1067	                .is_some_and(|used| args_conflict(cmd, arg, used))
1068	        })
1069	    });
1070	}
