1072	/// Record an argument seen on the command line, keeping the first occurrence
1073	/// only so that repeating a flag neither alters filtering nor restores
1074	/// candidates already excluded.
1075	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
1076	    if !used_args.iter().any(|used| used == id) {
1077	        used_args.push(id.clone());
1078	    }
1079	}
