1081	/// De-duplicate flag candidates.
1082	///
1083	/// With an empty word every long spelling of an argument (its long name and
1084	/// visible aliases) is offered, while short spellings are still collapsed to
1085	/// the canonical short and dropped for arguments that also have a long form.
1086	/// Once a prefix is typed at most one spelling of an argument can match, so
1087	/// candidates are de-duplicated by argument id as before.
1088	fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
1089	    if empty_word {
1090	        let long_ids: std::collections::HashSet<String> = completions
1091	            .iter()
1092	            .filter(|candidate| {
1093	                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
1094	            })
1095	            .filter_map(|candidate| candidate.get_id().cloned())
1096	            .collect();
1097	        let mut seen_short_ids = std::collections::HashSet::new();
1098	        completions.retain(|candidate| {
1099	            let Some(id) = candidate.get_id() else {
1100	                return true;
1101	            };
1102	            if candidate.get_value().starts_with("--") {
1103	                // Keep the long name and every visible alias.
1104	                true
1105	            } else if long_ids.contains(id) {
1106	                // Prefer the long forms over the short ones.
1107	                false
1108	            } else {
1109	                seen_short_ids.insert(id.clone())
1110	            }
1111	        });
1112	    } else {
1113	        let mut seen_ids = std::collections::HashSet::new();
1114	        completions.retain(|candidate| {
1115	            if let Some(id) = candidate.get_id().cloned() {
1116	                seen_ids.insert(id)
1117	            } else {
1118	                true
1119	            }
1120	        });
1121	    }
1122	}
