1124	/// Whether `first` and `second` conflict, no matter which one declares it.
1125	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
1126	    cmd.get_arg_conflicts_with(first)
1127	        .iter()
1128	        .any(|c| c.get_id() == second.get_id())
1129	        || cmd
1130	            .get_arg_conflicts_with(second)
1131	            .iter()
1132	            .any(|c| c.get_id() == first.get_id())
1133	}
