1135	/// The positional the parser would fill at `pos_index`.
1136	///
1137	/// A `last(true)` positional only exists after `--`; before the terminator
1138	/// the parser rejects values for it, so it must not be completed.
1139	fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
1140	    cmd.get_positionals()
1141	        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
1142	}
