1144	/// Parse the positional arguments. Return the new state and the new positional index.
1145	fn parse_positional<'a>(
1146	    cmd: &clap::Command,
1147	    pos_index: usize,
1148	    is_escaped: bool,
1149	    state: ParseState<'a>,
1150	) -> (ParseState<'a>, usize) {
1151	    let pos_arg = cmd
1152	        .get_positionals()
1153	        .find(|p| p.get_index() == Some(pos_index));
1154	    let num_args = pos_arg
1155	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1156	        .unwrap_or(1);
1157	
1158	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1159	        if num_args > 1 {
1160	            (ParseState::Pos((pos_index, 1)), pos_index)
1161	        } else {
1162	            if is_escaped {
1163	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1164	            } else {
1165	                (ParseState::ValueDone, pos_index + 1)
1166	            }
1167	        }
1168	    };
1169	    match state {
1170	        ParseState::ValueDone => {
1171	            update_state_with_new_positional(pos_index)
1172	        },
1173	        ParseState::Pos((prev_pos_index, num_arg)) => {
1174	            if prev_pos_index == pos_index {
1175	                if num_arg + 1 < num_args {
1176	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1177	                } else {
1178	                    if is_escaped {
1179	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1180	                    } else {
1181	                        (ParseState::ValueDone, pos_index + 1)
1182	                    }
1183	                }
1184	            } else {
1185	                update_state_with_new_positional(pos_index)
1186	            }
1187	        }
1188	        ParseState::Opt(..) => unreachable!(
1189	            "This branch won't be hit,
1190	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1191	        ),
1192	    }
1193	}
1194	
1195	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1196	    cmd.get_positionals()
1197	        .find(|a| a.get_index() == Some(pos_index))
1198	        .map(|p| p.is_allow_hyphen_values_set())
1199	        .unwrap_or(false)
1200	}
1201	
1202	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
1203	/// for, honoring the value delimiter.
1204	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
1205	    match (opt.get_value_delimiter(), value.to_str()) {
1206	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
1207	        _ => 1,
1208	    }
1209	}
1210	
1211	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1212	    let val = arg.to_value_os();
1213	    if val.starts_with("-") {
1214	        if let ParseState::Opt(state) = state {
1215	            return state.opt.is_allow_hyphen_values_set();
1216	        }
1217	    }
1218	
1219	    false
1220	}
1221	
1222	/// Whether `arg` is the standalone value terminator of a pending option.
1223	///
1224	/// Like the parser, an attached value (`--opt=;`) is not a terminator: the
1225	/// word must consist of the terminator alone.
1226	fn is_value_terminator(opt: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1227	    opt.get_value_terminator()
1228	        .is_some_and(|term| arg.to_value_os() == OsStr::new(term.as_str()))
1229	}
1230	
1231	/// Whether the parser would route this word through flag/escape parsing before
1232	/// a pending option gets to consume it as a value.
1233	fn is_flag_like(arg: &clap_lex::ParsedArg<'_>) -> bool {
1234	    arg.is_escape() || arg.to_long().is_some() || arg.to_short().is_some()
1235	}
1236	
1237	/// Whether a word can terminate a still-open multi-value option and start a
1238	/// new argument instead, the way the parser would read it.
1239	///
1240	/// While an option still owes values, the parser greedily consumes every plain
1241	/// word as one of its values; only flag-like words can switch to another
1242	/// argument. An option that accepts hyphen values consumes those too.
1243	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1244	    if arg.is_escape() {
1245	        // `--` cancels every pending option unless its values may start with `--`.
1246	        return !pending.is_allow_hyphen_values_set();
1247	    }
1248	    if !arg.to_value_os().starts_with("-") {
1249	        // A plain word is always another value of the pending option.
1250	        return false;
1251	    }
1252	    if pending.is_allow_hyphen_values_set() {
1253	        return false;
1254	    }
1255	    // `-` is a stdio/value, not a flag.
1256	    if arg.is_stdio() {
1257	        return false;
1258	    }
1259	    // Both long and short flag styles can start a new argument; unknown flags
1260	    // still switch (and error during parsing) rather than become option values.
1261	    arg.to_long().is_some() || arg.to_short().is_some()
1262	}
