use std::ffi::OsStr;
use std::ffi::OsString;

use clap_lex::OsStrExt as _;

use super::ArgValueCandidates;
use super::ArgValueCompleter;
use super::CompletionCandidate;
use super::SubcommandCandidates;
use super::ValueCandidates;
use super::custom::complete_path;
use super::custom::possible_value_candidates;

/// Complete the given command, shell-agnostic
pub fn complete(
    cmd: &mut clap::Command,
    args: Vec<OsString>,
    arg_index: usize,
    current_dir: Option<&std::path::Path>,
) -> Result<Vec<CompletionCandidate>, std::io::Error> {
    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
    cmd.build();

    let mut raw_args = clap_lex::RawArgs::new(args);
    let mut cursor = raw_args.cursor();
    let mut target_cursor = raw_args.cursor();
    raw_args.seek(
        &mut target_cursor,
        clap_lex::SeekFrom::Start(arg_index as u64),
    );
    // As we loop, `cursor` will always be pointing to the next item
    raw_args.next_os(&mut target_cursor);
    debug!("complete: target_cursor={target_cursor:?}");

    // TODO: Multicall support
    if !cmd.is_no_binary_name_set() {
        raw_args.next_os(&mut cursor);
    }

    let mut current_cmd = &*cmd;
    let mut pos_index = 1;
    let mut is_escaped = false;
    let mut next_state = ParseState::ValueDone;
    let mut used_args = Vec::<clap::Id>::new();
    while let Some(arg) = raw_args.next(&mut cursor) {
        let current_state = next_state;
        next_state = ParseState::ValueDone;
        debug!(
            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
            arg.to_value_os(),
        );
        if let ParseState::Opt(state) = &current_state {
            // A value terminator ends a multi-value option regardless of the
            // word's shape: unlike a flag-like word, it never starts a new
            // argument, and unlike any other word, it is never one of the
            // option's values. A flag-shaped terminator only wins over flag
            // parsing when the option accepts hyphen values, matching the
            // parser's precedence.
            let opt = state.opt;
            if is_value_terminator(opt, &arg)
                && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
            {
                if cursor == target_cursor {
                    // The cursor sits on the terminator itself. Complete as if
                    // it had already been submitted and an empty word followed,
                    // so ordinary completion resumes and the terminator is not
                    // offered as a candidate.
                    raw_args.insert(&target_cursor, [OsString::new()]);
                    let mut word_cursor = target_cursor;
                    let word = raw_args
                        .next(&mut word_cursor)
                        .expect("an empty word was just inserted");
                    return complete_arg(
                        &word,
                        current_cmd,
                        current_dir,
                        pos_index,
                        is_escaped,
                        ParseState::ValueDone,
                        &used_args,
                    );
                }
                next_state = ParseState::ValueDone;
                continue;
            }
        }
        if cursor == target_cursor {
            return complete_arg(
                &arg,
                current_cmd,
                current_dir,
                pos_index,
                is_escaped,
                current_state,
                &used_args,
            );
        }

        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
            if let Ok(value) = arg.to_value() {
                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
                    current_cmd = next_cmd;
                    pos_index = 1;
                    used_args.clear();
                    continue;
                }
            }
        }

        // A strict delimited group whose previous word opened another fragment
        // (a trailing delimiter) or went invalid owns the next word outright: a
        // flag, the `--` escape, or a subcommand name is then another value of
        // the group, never a scope switch. A continuation word that fills the
        // group closes it; otherwise the group stays pending for its remaining
        // fragments.
        if let ParseState::Opt(state) = &current_state {
            if state.is_strict_group() && (state.open || state.invalid) {
                let mut state = state.clone();
                state.observe(arg.to_value_os(), false);
                next_state =
                    if !state.invalid && !state.open && state.used.len() == state.capacity() {
                        ParseState::ValueDone
                    } else {
                        ParseState::Opt(state)
                    };
                continue;
            }
        }

        if is_escaped {
            (next_state, pos_index) =
                parse_positional(current_cmd, pos_index, is_escaped, current_state);
        } else if arg.is_escape() {
            is_escaped = true;
            // Like the parser, `--` jumps straight to a `last(true)`
            // positional, skipping any unfilled positionals.
            if let Some(last_index) = current_cmd
                .get_positionals()
                .filter(|p| p.is_last_set())
                .filter_map(|p| p.get_index())
                .max()
            {
                pos_index = last_index;
            }
        } else if opt_allows_hyphen(&current_state, &arg) {
            match current_state {
                ParseState::Opt(mut state) => {
                    state.observe(arg.to_value_os(), false);
                    next_state = state.finish();
                }
                _ => unreachable!("else branch is only reachable in Opt state"),
            }
        } else if let Some((flag, value)) = arg.to_long() {
            if let Ok(flag) = flag {
                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));

                if let Some(opt) = opt {
                    record_used_arg(&mut used_args, opt.get_id());
                    if opt.get_num_args().expect("built").takes_values() {
                        // An attached value (`--opt=value`) counts toward the
                        // option's values just like a space-separated one, so
                        // that completing after `--opt=value` sees the same
                        // state as completing after `--opt value`.
                        // An empty attached value (`--opt=`) types no value
                        // yet, so the option stays pending.
                        let mut state = OptState::new(opt);
                        if let Some(value) = value.filter(|v| !v.is_empty()) {
                            state.observe(value, true);
                        }
                        next_state = state.finish();
                    };
                } else if pos_allows_hyphen(current_cmd, pos_index) {
                    (next_state, pos_index) =
                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
                }
            }
        } else if let Some(short) = arg.to_short() {
            let (_, matched_opts, takes_value_opt, mut short) =
                parse_shortflags(current_cmd, short);
            for opt in &matched_opts {
                record_used_arg(&mut used_args, opt.get_id());
            }
            if let Some(opt) = takes_value_opt {
                // An attached value (`-ovalue`, `-o=value`) counts toward the
                // option's values just like a space-separated one. An empty
                // attached value (`-o=`) types no value yet, so the option
                // stays pending instead of being treated as satisfied.
                let mut state = OptState::new(opt);
                if let Some(value) = short
                    .next_value_os()
                    .map(|v| v.strip_prefix("=").unwrap_or(v))
                    .filter(|v| !v.is_empty())
                {
                    state.observe(value, true);
                }
                next_state = state.finish();
            } else if pos_allows_hyphen(current_cmd, pos_index) {
                (next_state, pos_index) =
                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
            }
        } else {
            match current_state {
                ParseState::ValueDone | ParseState::Pos(..) => {
                    (next_state, pos_index) =
                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
                }
                ParseState::Opt(mut state) => {
                    state.observe(arg.to_value_os(), false);
                    next_state = state.finish();
                }
            }
        }
    }

    Err(std::io::Error::other("no completion generated"))
}

#[derive(Debug, PartialEq, Eq, Clone)]
enum ParseState<'a> {
    /// Parsing a value done, there is no state to record.
    ValueDone,

    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
    Pos((usize, usize)),

    /// Parsing a optional flag argument
    Opt(OptState<'a>),
}

/// State kept while the values of an option are still being parsed.
#[derive(Debug, PartialEq, Eq, Clone)]
struct OptState<'a> {
    opt: &'a clap::Arg,
    /// Shell-word values consumed, counted the way the parser does so that
    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments
    /// rather than delimiter-separated fragments.
    words: usize,
    /// Canonical possible-value names of the valid, committed fragments of
    /// the current occurrence. Only populated for strict delimited groups.
    used: Vec<String>,
    /// Whether the most recent shell word ended with the value delimiter, so
    /// the word under the cursor is still filling this group (and may not
    /// switch scope no matter how it is shaped).
    open: bool,
    /// Whether a committed fragment of the current group was invalid (empty,
    /// unknown, duplicated, or past the group's capacity). Such a group stays
    /// locked on value completion and never yields candidates or lets a later
    /// word switch scope.
    invalid: bool,
}

impl<'a> OptState<'a> {
    fn new(opt: &'a clap::Arg) -> Self {
        Self {
            opt,
            words: 0,
            used: Vec::new(),
            open: false,
            invalid: false,
        }
    }

    fn is_strict_group(&self) -> bool {
        is_strict_group_arg(self.opt)
    }

    /// Maximum number of values the option accepts; for strict delimited
    /// groups this is the number of fragments allowed in one occurrence.
    fn capacity(&self) -> usize {
        self.opt.get_num_args().expect("built").max_values()
    }

    /// Record a shell word as a value of this option.
    ///
    /// `attached` marks a value glued to its flag (`--opt=a,b`). For options
    /// whose delimiter is not a strict group, such a word counts every
    /// delimiter-separated fragment toward the value range; a space-separated
    /// word counts once. For strict groups the fragments are instead validated
    /// into `used`, except the empty slot still being typed after a trailing
    /// delimiter.
    fn observe(&mut self, word: &OsStr, attached: bool) {
        if !self.is_strict_group() {
            let count = if attached {
                attached_value_count(self.opt, word)
            } else {
                1
            };
            self.words += count;
            return;
        }

        self.words += 1;
        if self.invalid {
            return;
        }
        let delimiter = self.opt.get_value_delimiter().expect("strict group");
        let capacity = self.capacity();
        self.open = word.to_string_lossy().ends_with(delimiter);
        let Some(word) = word.to_str() else {
            self.invalid = true;
            return;
        };
        let mut fragments = word.split(delimiter);
        if self.open {
            // A trailing delimiter opens the slot still being typed, so its
            // empty fragment is not a committed value.
            fragments.next_back();
        }
        for fragment in fragments {
            if self.used.len() >= capacity {
                self.invalid = true;
                break;
            }
            match canonical_possible_value(self.opt, fragment) {
                Some(name) if !self.used.contains(&name) => self.used.push(name),
                _ => {
                    // Empty (also a doubled delimiter), unknown, or duplicated
                    // fragment: the parser would reject this group.
                    self.invalid = true;
                    break;
                }
            }
        }
    }

    /// Consume a value and return the state parsing should resume with.
    ///
    /// The delimiter separates several fragments within one shell word, so a
    /// word that does not end with the delimiter is a complete value group and
    /// ordinary parsing resumes on the next word. A trailing delimiter instead
    /// opens a fragment still being typed, and an invalid committed fragment
    /// cannot be salvaged; both keep the group locked on values. An empty
    /// attached value (`--opt=`) leaves the option waiting for its first value.
    fn finish(self) -> ParseState<'a> {
        if self.is_strict_group() {
            if self.words == 0 || self.invalid || self.open {
                ParseState::Opt(self)
            } else {
                ParseState::ValueDone
            }
        } else if self.words >= self.capacity() {
            ParseState::ValueDone
        } else {
            ParseState::Opt(self)
        }
    }
}

/// Whether an option's values form a delimited group that can hold more than
/// one fragment and whose fragments are validated while typed.
///
/// Single-value options (a maximum of one) are excluded: their delimiter only
/// joins several suggestions into one word, so completed fragments are not
/// validated against each other.
fn is_strict_group_arg(arg: &clap::Arg) -> bool {
    arg.get_value_delimiter().is_some()
        && arg.get_num_args().expect("built").max_values() > 1
        && possible_values(arg).is_some()
}

/// The canonical possible-value name for `fragment`, honoring aliases and the
/// argument's case-insensitivity, or `None` when it is not a legal value.
fn canonical_possible_value(arg: &clap::Arg, fragment: &str) -> Option<String> {
    let ignore_case = arg.is_ignore_case_set();
    possible_values(arg)?
        .find(|value| value.matches(fragment, ignore_case))
        .map(|value| value.get_name().to_owned())
}

/// Complete the word under the cursor for a strict delimited group.
///
/// Fragments already committed in earlier shell words are read from `state`;
/// fragments committed within the word under the cursor are validated here.
/// The fragment still being typed is matched against the possible values, and
/// every suggestion keeps the typed prefix (prior fragments and delimiters).
/// Any empty, unknown, duplicated, or over-capacity fragment yields an empty
/// result.
fn complete_strict_group(cursor: &str, state: &OptState<'_>) -> Vec<CompletionCandidate> {
    debug!(
        "complete_strict_group: arg={:?}, cursor={cursor:?}, used={:?}, invalid={}",
        state.opt.get_id(),
        state.used,
        state.invalid
    );
    if state.invalid {
        return Vec::new();
    }
    let delimiter = state.opt.get_value_delimiter().expect("strict group");
    let capacity = state.capacity();

    let ends_with_delimiter = cursor.ends_with(delimiter);
    let mut parts = cursor.split(delimiter);
    let typed = if ends_with_delimiter {
        // The cursor sits right after a delimiter: the trailing empty element
        // is the fresh fragment being typed, not a committed value.
        parts.next_back();
        ""
    } else {
        parts.next_back().unwrap_or("")
    };

    let mut used = state.used.clone();
    for fragment in parts {
        if used.len() >= capacity {
            return Vec::new();
        }
        match canonical_possible_value(state.opt, fragment) {
            Some(name) if !used.contains(&name) => used.push(name),
            _ => return Vec::new(),
        }
    }

    if used.len() >= capacity {
        // Every slot is taken; there is no room for another fragment.
        return Vec::new();
    }

    // Retain the text typed before the current fragment, including the last
    // delimiter, so suggestions replace only the fragment under the cursor.
    let prefix = cursor
        .rfind(delimiter)
        .map(|pos| cursor[..pos + delimiter.len_utf8()].to_owned());

    let possible = possible_values(state.opt).expect("strict group");
    let mut values = complete_candidates_str(typed, possible_value_candidates(possible));
    // A value already committed to the group cannot be repeated.
    values.retain(|candidate| {
        candidate
            .get_value()
            .to_str()
            .is_none_or(|name| !used.iter().any(|used| used == name))
    });

    if let Some(prefix) = prefix {
        values = values
            .into_iter()
            .map(|comp| comp.add_prefix(prefix.clone()))
            .collect();
    }
    values = values
        .into_iter()
        .map(|comp| {
            if comp.get_tag().is_some() {
                comp
            } else {
                comp.tag(Some(state.opt.to_string().into()))
            }
        })
        .collect();

    values
}

fn complete_arg(
    arg: &clap_lex::ParsedArg<'_>,
    cmd: &clap::Command,
    current_dir: Option<&std::path::Path>,
    pos_index: usize,
    is_escaped: bool,
    state: ParseState<'_>,
    used_args: &[clap::Id],
) -> Result<Vec<CompletionCandidate>, std::io::Error> {
    debug!(
        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
        arg,
        cmd.get_name(),
        current_dir,
        pos_index,
        state
    );
    let mut completions = Vec::<CompletionCandidate>::new();

    match state {
        ParseState::ValueDone => {
            if !is_escaped {
                if let Ok(value) = arg.to_value() {
                    completions.extend(complete_subcommand(value, cmd));
                }
            }

            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
                completions.extend(complete_arg_value(
                    arg.to_value(),
                    positional,
                    current_dir,
                    0,
                ));
            }
            if !is_escaped {
                completions.extend(complete_option(arg, cmd, current_dir));
            }
        }
        ParseState::Pos((_, num_arg)) => {
            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
                completions.extend(complete_arg_value(
                    arg.to_value(),
                    positional,
                    current_dir,
                    num_arg.saturating_sub(1),
                ));
                if !is_escaped
                    && positional
                        .get_num_args()
                        .is_some_and(|num_args| num_arg >= num_args.min_values())
                {
                    completions.extend(complete_option(arg, cmd, current_dir));
                }
            }
        }
        ParseState::Opt(state) => {
            if state.is_strict_group() {
                // Every word belongs to the pending delimited group until it is
                // complete; it is never an option, positional, or subcommand.
                if let Ok(cursor) = arg.to_value() {
                    completions.extend(complete_strict_group(cursor, &state));
                }
            } else {
                let opt = state.opt;
                // `words` counts already-consumed values; the word under the
                // cursor is the next one, so the option sees one more value.
                let count = state.words + 1;
                completions.extend(complete_arg_value(
                    arg.to_value(),
                    opt,
                    current_dir,
                    count.saturating_sub(1),
                ));
                let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
                if count > min && can_switch_to_other_arg(opt, arg) {
                    // The option's required values are satisfied and this word
                    // would be parsed as a new flag rather than another value, so
                    // also complete it as a positional, flag, option or subcommand.
                    completions.extend(complete_arg(
                        arg,
                        cmd,
                        current_dir,
                        pos_index,
                        is_escaped,
                        ParseState::ValueDone,
                        used_args,
                    )?);
                }
            }
        }
    }
    filter_unavailable_args(&mut completions, cmd, used_args);
    if completions.iter().any(|a| !a.is_hide_set()) {
        completions.retain(|a| !a.is_hide_set());
    }
    dedup_argument_candidates(&mut completions, arg.is_empty());

    let mut tags = Vec::new();
    for candidate in &completions {
        let tag = candidate.get_tag().cloned();
        if !tags.contains(&tag) {
            tags.push(tag);
        }
    }
    completions.sort_by_key(|c| {
        (
            tags.iter().position(|t| c.get_tag() == t.as_ref()),
            c.get_display_order(),
        )
    });

    Ok(completions)
}

fn complete_option(
    arg: &clap_lex::ParsedArg<'_>,
    cmd: &clap::Command,
    current_dir: Option<&std::path::Path>,
) -> Vec<CompletionCandidate> {
    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
    let mut completions = Vec::<CompletionCandidate>::new();
    if arg.is_empty() {
        completions.extend(longs_and_visible_aliases(cmd));
        completions.extend(hidden_longs_aliases(cmd));

        let dash_or_arg = if arg.is_empty() {
            "-".into()
        } else {
            arg.to_value_os().to_string_lossy()
        };
        completions.extend(
            shorts_and_visible_aliases(cmd)
                .into_iter()
                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
        );
    } else if arg.is_stdio() {
        // HACK: Assuming knowledge of is_stdio
        let dash_or_arg = if arg.is_empty() {
            "-".into()
        } else {
            arg.to_value_os().to_string_lossy()
        };
        completions.extend(
            shorts_and_visible_aliases(cmd)
                .into_iter()
                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
        );

        completions.extend(longs_and_visible_aliases(cmd));
        completions.extend(hidden_longs_aliases(cmd));
    } else if arg.is_escape() {
        // HACK: Assuming knowledge of is_escape
        completions.extend(longs_and_visible_aliases(cmd));
        completions.extend(hidden_longs_aliases(cmd));
    } else if let Some((flag, value)) = arg.to_long() {
        if let Ok(flag) = flag {
            if let Some(value) = value {
                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
                    if is_strict_group_arg(arg) {
                        // The whole attached word is the delimited group being
                        // typed, so its committed fragments are validated in
                        // place and only the fragment after the last delimiter
                        // is offered; the flag spelling is re-prefixed below.
                        if let Some(value) = value.to_str() {
                            let state = OptState::new(arg);
                            completions.extend(
                                complete_strict_group(value, &state)
                                    .into_iter()
                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
                            );
                        }
                    } else {
                        completions.extend(
                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
                                .into_iter()
                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
                        );
                    }
                }
            } else {
                completions.extend(
                    longs_and_visible_aliases(cmd)
                        .into_iter()
                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
                );
                completions.extend(
                    hidden_longs_aliases(cmd)
                        .into_iter()
                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
                );
            }
        }
    } else if let Some(short) = arg.to_short() {
        if !short.is_negative_number() {
            // Find the first takes_values option.
            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);

            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
            if let Some(opt) = takes_value_opt {
                let mut peek_short = short.clone();
                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
                    short.next_flag();
                    true
                } else {
                    false
                };

                let value = short.next_value_os().unwrap_or(OsStr::new(""));
                let group_completions = if is_strict_group_arg(opt) {
                    value
                        .to_str()
                        .map(|value| complete_strict_group(value, &OptState::new(opt)))
                        .unwrap_or_default()
                } else {
                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
                };
                completions.extend(group_completions.into_iter().map(|comp| {
                    let sep = if has_equal { "=" } else { "" };
                    comp.add_prefix(format!("-{leading_flags}{sep}"))
                }));
            } else {
                completions.extend(
                    shorts_and_visible_aliases(cmd)
                        .into_iter()
                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
                );
            }
        }
    }
    debug!("complete_option: completions={completions:?}");
    completions
}

fn complete_arg_value(
    value: Result<&str, &OsStr>,
    arg: &clap::Arg,
    current_dir: Option<&std::path::Path>,
    arg_index: usize,
) -> Vec<CompletionCandidate> {
    let mut values = Vec::new();
    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");

    let (prefix, value) =
        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));

    let value_os = match value {
        Ok(value) => OsStr::new(value),
        Err(value_os) => value_os,
    };

    if let Some(completer) = arg.get::<ArgValueCompleter>() {
        values.extend(completer.complete_at(arg_index, value_os));
    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
        values.extend(complete_value_candidates(
            value_os,
            completer.value_candidates(),
        ));
    } else if let Some(possible_values) = possible_values(arg) {
        if let Ok(value) = value {
            values.extend(complete_candidates_str(
                value,
                possible_value_candidates(possible_values),
            ));
        }
    } else {
        match arg.get_value_hint() {
            clap::ValueHint::Unknown | clap::ValueHint::Other => {
                // Should not complete
            }
            clap::ValueHint::AnyPath => {
                values.extend(complete_path(value_os, current_dir, &|_| true));
            }
            clap::ValueHint::FilePath => {
                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
            }
            clap::ValueHint::DirPath => {
                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
            }
            clap::ValueHint::ExecutablePath => {
                use is_executable::IsExecutable;
                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
            }
            clap::ValueHint::CommandName
            | clap::ValueHint::CommandString
            | clap::ValueHint::CommandWithArguments
            | clap::ValueHint::Username
            | clap::ValueHint::Hostname
            | clap::ValueHint::Url
            | clap::ValueHint::EmailAddress => {
                // No completion implementation
            }
            _ => {
                // Safe-ish fallback
                values.extend(complete_path(value_os, current_dir, &|_| true));
            }
        }

        values.sort();
    }

    if let Some(prefix) = prefix {
        values = values
            .into_iter()
            .map(|comp| comp.add_prefix(prefix))
            .collect();
    }
    values = values
        .into_iter()
        .map(|comp| {
            if comp.get_tag().is_some() {
                comp
            } else {
                comp.tag(Some(arg.to_string().into()))
            }
        })
        .collect();

    debug!("complete_arg_value: values={values:?}");
    values
}

fn rsplit_delimiter<'s, 'o>(
    value: Result<&'s str, &'o OsStr>,
    delimiter: Option<char>,
) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
    let delimiter = delimiter?;
    let value = value.ok()?;
    let pos = value.rfind(delimiter)?;
    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
    Some((Some(prefix), Ok(value)))
}

fn complete_value_candidates(
    value: &OsStr,
    completer: &dyn ValueCandidates,
) -> Vec<CompletionCandidate> {
    debug!("complete_value_candidates: value={value:?}");

    let mut values = completer.candidates();
    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
    values
}

fn complete_candidates_str(
    value: &str,
    mut values: Vec<CompletionCandidate>,
) -> Vec<CompletionCandidate> {
    debug!("complete_candidates_str: value={value:?}");

    values.retain(|comp| comp.get_value().starts_with(value));
    values
}

fn complete_value_candidates_str(
    value: &str,
    completer: &dyn ValueCandidates,
) -> Vec<CompletionCandidate> {
    debug!("complete_value_candidates_str: value={value:?}");

    complete_candidates_str(value, completer.candidates())
}

fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
    debug!(
        "complete_subcommand: cmd={:?}, value={:?}",
        cmd.get_name(),
        value
    );

    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
        .into_iter()
        .filter(|x| x.get_value().starts_with(value))
        .collect();
    if cmd.is_allow_external_subcommands_set() {
        let external_completer = cmd.get::<SubcommandCandidates>();
        if let Some(completer) = external_completer {
            scs.extend(complete_value_candidates_str(
                value,
                completer.value_candidates(),
            ));
        }
    }

    scs.dedup();
    scs
}

/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
/// Includes `help` and `version` depending on the [`clap::Command`] settings.
fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
    debug!("longs: name={}", p.get_name());

    p.get_arguments()
        .filter_map(|a| {
            a.get_long_and_visible_aliases().map(|longs| {
                longs
                    .into_iter()
                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
            })
        })
        .flatten()
        .collect()
}

/// Gets all the long hidden aliases and flags of a [`clap::Command`].
fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
    debug!("longs: name={}", p.get_name());

    p.get_arguments()
        .filter_map(|a| {
            a.get_aliases().map(|longs| {
                longs.into_iter().map(|s| {
                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
                })
            })
        })
        .flatten()
        .collect()
}

/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
/// Includes `h` and `V` depending on the [`clap::Command`] settings.
fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
    debug!("shorts: name={}", p.get_name());

    p.get_arguments()
        .filter_map(|a| {
            a.get_short_and_visible_aliases().map(|shorts| {
                shorts.into_iter().map(|s| {
                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
                        a.get_help()
                            .cloned()
                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
                    )
                })
            })
        })
        .flatten()
        .collect()
}

fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
    candidate
        .help(arg.get_help().cloned())
        .id(Some(format!("arg::{}", arg.get_id())))
        .tag(Some(
            arg.get_help_heading()
                .unwrap_or("Options")
                .to_owned()
                .into(),
        ))
        .display_order(Some(arg.get_display_order()))
        .hide(arg.is_hide_set())
}

/// Get the possible values for completion
fn possible_values(
    a: &clap::Arg,
) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
    if !a.get_num_args().expect("built").takes_values() {
        None
    } else {
        a.get_value_parser().possible_values()
    }
}

/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
///
/// Subcommand `rustup toolchain install` would be converted to
/// `("install", "rustup toolchain install")`.
fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
    debug!("subcommands: name={}", p.get_name());
    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
    p.get_subcommands()
        .flat_map(|sc| {
            sc.get_name_and_visible_aliases()
                .into_iter()
                .map(|s| populate_command_candidate(s, p, sc))
                .chain(
                    sc.get_aliases()
                        .map(|s| populate_command_candidate(s, p, sc).hide(true)),
                )
        })
        .collect()
}

fn populate_command_candidate(
    candidate_name: &str,
    cmd: &clap::Command,
    subcommand: &clap::Command,
) -> CompletionCandidate {
    CompletionCandidate::new(candidate_name.to_owned())
        .help(subcommand.get_about().cloned())
        .id(Some(format!("command::{candidate_name}")))
        .tag(Some(
            cmd.get_subcommand_help_heading()
                .unwrap_or("Commands")
                .to_owned()
                .into(),
        ))
        .display_order(Some(subcommand.get_display_order()))
        .hide(subcommand.is_hide_set())
}

/// Parse the short flags and find the first `takes_values` option.
///
/// Returns the raw leading flags, every matched argument, the first
/// `takes_values` option (if any), and the remaining unparsed flags.
fn parse_shortflags<'c, 's>(
    cmd: &'c clap::Command,
    mut short: clap_lex::ShortFlags<'s>,
) -> (
    String,
    Vec<&'c clap::Arg>,
    Option<&'c clap::Arg>,
    clap_lex::ShortFlags<'s>,
) {
    let takes_value_opt;
    let mut matched_opts = Vec::new();
    let mut leading_flags = String::new();
    // Find the first takes_values option.
    loop {
        match short.next_flag() {
            Some(Ok(opt)) => {
                leading_flags.push(opt);
                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
                if let Some(opt) = opt {
                    matched_opts.push(opt);
                }
                if opt
                    .map(|o| o.get_num_args().expect("built").takes_values())
                    .unwrap_or(false)
                {
                    takes_value_opt = opt;
                    break;
                }
            }
            Some(Err(_)) | None => {
                takes_value_opt = None;
                break;
            }
        }
    }

    (leading_flags, matched_opts, takes_value_opt, short)
}

/// Whether the argument can be addressed by the long flag `flag`,
/// including visible and hidden aliases.
fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
    arg.get_long() == Some(flag)
        || arg
            .get_all_aliases()
            .is_some_and(|aliases| aliases.contains(&flag))
}

/// Whether the argument can be addressed by the short flag `flag`,
/// including visible and hidden aliases.
fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
    arg.get_short() == Some(flag)
        || arg
            .get_all_short_aliases()
            .is_some_and(|aliases| aliases.contains(&flag))
}

/// Remove argument candidates that are unavailable given the arguments
/// already present on the command line.
///
/// Two rules apply:
/// - Non-multiple argument groups: once any member of such a group is on the
///   command line, every member of that group (including the selected one and
///   all of its aliases) is removed, mirroring the parser's one-of constraint.
/// - Explicit conflicts: a candidate that conflicts with an already-used
///   argument is removed; conflicts only need to be declared on one side.
///
/// Anything that is not an argument candidate (positional values,
/// subcommands, custom candidates) is left untouched.
fn filter_unavailable_args(
    completions: &mut Vec<CompletionCandidate>,
    cmd: &clap::Command,
    used_args: &[clap::Id],
) {
    if used_args.is_empty() {
        return;
    }

    // Members of non-multiple groups that already have a member present.
    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
        let members: Vec<&clap::Id> = group.get_args().collect();
        if members
            .iter()
            .any(|id| used_args.iter().any(|used| used == *id))
        {
            excluded_by_group.extend(members.into_iter().cloned());
        }
    }

    completions.retain(|candidate| {
        let Some(arg) = candidate
            .get_id()
            .and_then(|id| id.strip_prefix("arg::"))
            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
        else {
            return true;
        };
        if excluded_by_group.contains(arg.get_id()) {
            return false;
        }
        !used_args.iter().any(|used_id| {
            cmd.get_arguments()
                .find(|a| a.get_id() == used_id)
                .is_some_and(|used| args_conflict(cmd, arg, used))
        })
    });
}

/// Record an argument seen on the command line, keeping the first occurrence
/// only so that repeating a flag neither alters filtering nor restores
/// candidates already excluded.
fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
    if !used_args.iter().any(|used| used == id) {
        used_args.push(id.clone());
    }
}

/// De-duplicate flag candidates.
///
/// With an empty word every long spelling of an argument (its long name and
/// visible aliases) is offered, while short spellings are still collapsed to
/// the canonical short and dropped for arguments that also have a long form.
/// Once a prefix is typed at most one spelling of an argument can match, so
/// candidates are de-duplicated by argument id as before.
fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
    if empty_word {
        let long_ids: std::collections::HashSet<String> = completions
            .iter()
            .filter(|candidate| {
                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
            })
            .filter_map(|candidate| candidate.get_id().cloned())
            .collect();
        let mut seen_short_ids = std::collections::HashSet::new();
        completions.retain(|candidate| {
            let Some(id) = candidate.get_id() else {
                return true;
            };
            if candidate.get_value().starts_with("--") {
                // Keep the long name and every visible alias.
                true
            } else if long_ids.contains(id) {
                // Prefer the long forms over the short ones.
                false
            } else {
                seen_short_ids.insert(id.clone())
            }
        });
    } else {
        let mut seen_ids = std::collections::HashSet::new();
        completions.retain(|candidate| {
            if let Some(id) = candidate.get_id().cloned() {
                seen_ids.insert(id)
            } else {
                true
            }
        });
    }
}

/// Whether `first` and `second` conflict, no matter which one declares it.
fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
    cmd.get_arg_conflicts_with(first)
        .iter()
        .any(|c| c.get_id() == second.get_id())
        || cmd
            .get_arg_conflicts_with(second)
            .iter()
            .any(|c| c.get_id() == first.get_id())
}

/// The positional the parser would fill at `pos_index`.
///
/// A `last(true)` positional only exists after `--`; before the terminator
/// the parser rejects values for it, so it must not be completed.
fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
    cmd.get_positionals()
        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
}

/// Parse the positional arguments. Return the new state and the new positional index.
fn parse_positional<'a>(
    cmd: &clap::Command,
    pos_index: usize,
    is_escaped: bool,
    state: ParseState<'a>,
) -> (ParseState<'a>, usize) {
    let pos_arg = cmd
        .get_positionals()
        .find(|p| p.get_index() == Some(pos_index));
    let num_args = pos_arg
        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
        .unwrap_or(1);

    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
        if num_args > 1 {
            (ParseState::Pos((pos_index, 1)), pos_index)
        } else {
            if is_escaped {
                (ParseState::Pos((pos_index, 1)), pos_index + 1)
            } else {
                (ParseState::ValueDone, pos_index + 1)
            }
        }
    };
    match state {
        ParseState::ValueDone => {
            update_state_with_new_positional(pos_index)
        },
        ParseState::Pos((prev_pos_index, num_arg)) => {
            if prev_pos_index == pos_index {
                if num_arg + 1 < num_args {
                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
                } else {
                    if is_escaped {
                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
                    } else {
                        (ParseState::ValueDone, pos_index + 1)
                    }
                }
            } else {
                update_state_with_new_positional(pos_index)
            }
        }
        ParseState::Opt(..) => unreachable!(
            "This branch won't be hit,
            because ParseState::Opt should not be seen as a positional argument and passed to this function."
        ),
    }
}

fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
    cmd.get_positionals()
        .find(|a| a.get_index() == Some(pos_index))
        .map(|p| p.is_allow_hyphen_values_set())
        .unwrap_or(false)
}

/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
/// for, honoring the value delimiter.
fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
    match (opt.get_value_delimiter(), value.to_str()) {
        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
        _ => 1,
    }
}

fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
    let val = arg.to_value_os();
    if val.starts_with("-") {
        if let ParseState::Opt(state) = state {
            return state.opt.is_allow_hyphen_values_set();
        }
    }

    false
}

/// Whether `arg` is the standalone value terminator of a pending option.
///
/// Like the parser, an attached value (`--opt=;`) is not a terminator: the
/// word must consist of the terminator alone.
fn is_value_terminator(opt: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
    opt.get_value_terminator()
        .is_some_and(|term| arg.to_value_os() == OsStr::new(term.as_str()))
}

/// Whether the parser would route this word through flag/escape parsing before
/// a pending option gets to consume it as a value.
fn is_flag_like(arg: &clap_lex::ParsedArg<'_>) -> bool {
    arg.is_escape() || arg.to_long().is_some() || arg.to_short().is_some()
}

/// Whether a word can terminate a still-open multi-value option and start a
/// new argument instead, the way the parser would read it.
///
/// While an option still owes values, the parser greedily consumes every plain
/// word as one of its values; only flag-like words can switch to another
/// argument. An option that accepts hyphen values consumes those too.
fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
    if arg.is_escape() {
        // `--` cancels every pending option unless its values may start with `--`.
        return !pending.is_allow_hyphen_values_set();
    }
    if !arg.to_value_os().starts_with("-") {
        // A plain word is always another value of the pending option.
        return false;
    }
    if pending.is_allow_hyphen_values_set() {
        return false;
    }
    // `-` is a stdio/value, not a flag.
    if arg.is_stdio() {
        return false;
    }
    // Both long and short flag styles can start a new argument; unknown flags
    // still switch (and error during parsing) rather than become option values.
    arg.to_long().is_some() || arg.to_short().is_some()
}

