fn external_bad_inputs_never_error() {
    let mut cmd = external_tool_cmd();
    let bad_lines: &[&[&str]] = &[
        // Illegal tag fragments and prefixes that match nothing.
        &["tool", "--tag", "bogus"],
        &["tool", "--tag=zzz"],
        &["tool", "--tag", "red,red"],
        &["tool", "--tag", "red,,green"],
        &["tool", "--tag", "red,green,blue,x"],
        &["tool", "x"],
        &["tool", "--bogus"],
        &["tool", "-x"],
